            font-family: 'Arial', sans-serif;
            font-size: 120px;
            font-weight: bold;
            color: #e94560;
            position: absolute;
            cursor: pointer;
            text-shadow: 3px 3px 6px rgba(0,0,0,0.7);
            user-select: none;
        }
    </style>
