<body>
    <div class="container">
        <div id="logo">DVD</div>
    </div>
    <script>
        const logo = document.getElementById('logo');
        let x = 10, y = 10;
        let vx = 3, vy = 2;
        let wallLeft = 5, wallRight = 75;
        let wallTop = 5, wallBottom = 55;

        function animate() {
            x += vx;
            y += vy;

            // Bounce off walls
            if (x <= wallLeft) { vx = Math.abs(vx); }
            if (x >= wallRight) { vx = -Math.abs(vx); }
            if (y <= wallTop) { vy = Math.abs(vy); }
            if (y >= wallBottom) { vy = -Math.abs(vy); }

            logo.style.left = x + 'px';
            logo.style.top = y + 'px';

            requestAnimationFrame(animate);
        }

        animate();
    </script>
</body>
